/* ---- Error codes (mailbox error field and op status) and diagnostics ---- */

/* Success. */
#define PSXW_ERR_NONE 0x00000000u

/* Unknown mailbox kind. */
#define PSXW_ERR_BAD_KIND 0x00000010u

/* Unknown op. */
#define PSXW_ERR_BAD_OP 0x00000011u

/* A length field is inconsistent or exceeds a buffer. */
